import{_ as i,C as e,c as a,o,a0 as t,b as l,w as r,a as n,G as s,a1 as d}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Campo di addestramento: Guida al fine settimana","description":"","frontmatter":{},"headers":[],"relativePath":"it/training-camp.md","filePath":"it/training-camp.md"}');const c=i({name:"it/training-camp.md"},[["render",function(i,u,c,p,g,m){const h=e("Mermaid");return o(),a("div",null,[u[2]||(u[2]=t('<h1 id="campo-di-addestramento-guida-al-fine-settimana" tabindex="-1">Campo di addestramento: Guida al fine settimana <a class="header-anchor" href="#campo-di-addestramento-guida-al-fine-settimana" aria-label="Permalink to &quot;Campo di addestramento: Guida al fine settimana&quot;">​</a></h1><h2 id="come-organizzare-un-campo-di-allenamento-di-fine-settimana-per-10-20-giocatori" tabindex="-1">Come organizzare un campo di allenamento di fine settimana per 10-20 giocatori <a class="header-anchor" href="#come-organizzare-un-campo-di-allenamento-di-fine-settimana-per-10-20-giocatori" aria-label="Permalink to &quot;Come organizzare un campo di allenamento di fine settimana per 10-20 giocatori&quot;">​</a></h2><p>Questa guida completa ti aiuta a organizzare e gestire un campo di allenamento di fine settimana che combina teoria, pratica e competizione. Combina i contenuti di mental game di questo sito con l&#39;applicazione pratica in pista per ottenere il massimo impatto.</p><div class="tip custom-block"><p class="custom-block-title">La filosofia del campo di addestramento</p><p><strong>La teoria senza pratica è solo informazione. La pratica senza teoria è solo ripetizione. La competizione senza riflessione è solo gioco.</strong> Questo fine settimana integra tutte e tre le cose per un apprendimento trasformativo.</p></div>',4)),(o(),l(d,null,{default:r(()=>[s(h,{id:"mermaid-14",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BWeekend%20Camp%5D%20--%3E%20B%5BFriday%3A%20Theory%5D%0A%20%20%20%20B%20--%3E%20C%5BSaturday%3A%20Practice%5D%0A%20%20%20%20C%20--%3E%20D%5BSunday%3A%20Competition%5D%0A%20%20%20%20D%20--%3E%20E%5BIntegration%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23f3e5f5%0A"})]),fallback:r(()=>[...u[0]||(u[0]=[n(" Loading... ",-1)])]),_:1})),u[3]||(u[3]=t('<h2 id="pianificazione-pre-campo" tabindex="-1">Pianificazione pre-campo <a class="header-anchor" href="#pianificazione-pre-campo" aria-label="Permalink to &quot;Pianificazione pre-campo&quot;">​</a></h2><h3 id="dimensione-e-struttura-del-gruppo" tabindex="-1">Dimensione e struttura del gruppo <a class="header-anchor" href="#dimensione-e-struttura-del-gruppo" aria-label="Permalink to &quot;Dimensione e struttura del gruppo&quot;">​</a></h3><p><strong>Ottimale:</strong> 10-20 giocatori</p><ul><li><strong>Piccolo campo (10-12):</strong> Condivisione più intima e profonda</li><li><strong>Campo grande (16-20):</strong> Prospettive più diversificate, richiede sottogruppi</li></ul><p><strong>Struttura del team:</strong></p><ul><li>Dividetevi in squadre da 3-4 per gli allenamenti e le gare</li><li>Mescola livelli di abilità e stili di gioco</li><li>Ruotare le squadre durante il fine settimana</li></ul><h3 id="requisiti-di-personale" tabindex="-1">Requisiti di personale <a class="header-anchor" href="#requisiti-di-personale" aria-label="Permalink to &quot;Requisiti di personale&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ruolo</th><th>Responsabilità</th><th>Quantità</th></tr></thead><tbody><tr><td><strong>Coordinatore delle prestazioni mentali</strong></td><td>Facilita sessioni teoriche, dinamiche di gruppo</td><td>1</td></tr><tr><td><strong>Coach tecnico</strong></td><td>Supervisionare la pratica, fornire feedback</td><td>1-2</td></tr><tr><td><strong>Direttore della competizione</strong></td><td>Gestire il torneo, gestire la logistica</td><td>1</td></tr><tr><td><strong>Personale di supporto</strong></td><td>Pasti, allestimento, amministrazione</td><td>1-2</td></tr></tbody></table><h3 id="requisiti-di-posizione" tabindex="-1">Requisiti di posizione <a class="header-anchor" href="#requisiti-di-posizione" aria-label="Permalink to &quot;Requisiti di posizione&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Esigenze della struttura</p><p><strong>Pista:</strong></p><ul><li>Terreni multipli (minimo 3-4 piste)</li><li>Superfici diverse se possibile (ghiaia, sabbia, duro)</li><li>Illuminazione per il gioco serale</li></ul><p><strong>Spazio interno:</strong></p><ul><li>Sala per 20 persone in cerchio (sessioni teoriche)</li><li>Separato dalla pista</li><li>Lavagna/proiettore</li><li>Sedili comodi</li></ul><p><strong>Alloggio:</strong></p><ul><li>In loco o nelle vicinanze (raggiungibile a piedi)</li><li>Le stanze condivise favoriscono il legame</li><li>Spazio tranquillo per la riflessione</li></ul><p><strong>Ristorazione:</strong></p><ul><li>Pasti incentrati sulla nutrizione (vedi <a href="./food">Guida alimentare</a>)</li><li>Evitare crolli di zucchero</li><li>Stazioni di idratazione</li></ul></div><h3 id="lista-di-controllo-dei-materiali" tabindex="-1">Lista di controllo dei materiali <a class="header-anchor" href="#lista-di-controllo-dei-materiali" aria-label="Permalink to &quot;Lista di controllo dei materiali&quot;">​</a></h3><details class="details custom-block"><summary>Elenco completo dei materiali</summary><p><strong>Sessioni teoriche:</strong></p><ul><li>[ ] Sedie per il cerchio (no tavoli)</li><li>[ ] Bocce e cochonnet per il centro</li><li>[ ] Lavagne a fogli mobili e pennarelli</li><li>[ ] Note adesive</li><li>[ ] Schede di lavoro (Manuale utente, Critico interiore, ecc.)</li><li>[ ] Carta e penne</li><li>[ ] Proiettore (per i contenuti del sito web)</li></ul><p><strong>Sessioni di pratica:</strong></p><ul><li>[ ] Nastro di misurazione</li><li>[ ] Coni/marcatori per esercitazioni</li><li>[ ] Videocamera/treppiede</li><li>[ ] Appunti e carta (tracciamento)</li><li>[ ] Fischio</li></ul><p><strong>Concorrenza:</strong></p><ul><li>[ ] Fogli dei punteggi</li><li>[ ] Tabellone del torneo</li><li>[ ] Premi/riconoscimenti</li><li>[ ] Kit di pronto soccorso</li></ul><p><strong>Logistica:</strong></p><ul><li>[ ] Etichette identificative</li><li>[ ] Elenco dei partecipanti con contatti</li><li>[ ] Informazioni di contatto di emergenza</li><li>[ ] Bottiglie d&#39;acqua</li><li>[ ] Protezione solare</li><li>[ ] Fazzoletti (per il lavoro emotivo!)</li></ul></details><h2 id="programma-del-fine-settimana" tabindex="-1">Programma del fine settimana <a class="header-anchor" href="#programma-del-fine-settimana" aria-label="Permalink to &quot;Programma del fine settimana&quot;">​</a></h2><h3 id="venerdi-sera-3-ore" tabindex="-1">Venerdì sera (3 ore) <a class="header-anchor" href="#venerdi-sera-3-ore" aria-label="Permalink to &quot;Venerdì sera (3 ore)&quot;">​</a></h3><p><strong>18:00-18:30 - Arrivo e benvenuto</strong></p><ul><li>Registrazione</li><li>Assegnazione delle stanze</li><li>Panoramica del fine settimana</li></ul><p><strong>18:30-19:30 - Cena</strong></p><ul><li>Pasto incentrato sulla nutrizione</li><li>Presentazioni informali</li></ul><p><strong>19:30-22:30 - Sessione teorica: Fondamenti</strong></p><p>Utilizzare la <a href="./workshop">Guida al workshop</a> per una facilitazione dettagliata:</p><ol><li><strong>Regole di base (15 min)</strong> - Stabilire la sicurezza psicologica</li><li><strong>Matrice di check-in (20 min)</strong> - Valutare l&#39;energia del gruppo</li><li><strong>L&#39;Iceberg (30 min)</strong> - Esplora i pensieri interiori</li><li><strong>Manuale utente (45 min)</strong> - Sviluppare la comprensione del team</li><li><strong>La paura nel cappello (45 min)</strong> - Rompere l&#39;isolamento</li><li><strong>Check-Out (15 min)</strong> - Chiudi il cerchio</li></ol><p><strong>22:30 - Tempo libero</strong></p><ul><li>Socializzazione informale</li><li>Riposo e riflessione</li></ul>',23)),(o(),l(d,null,{default:r(()=>[s(h,{id:"mermaid-439",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFriday%20Theory%5D%20--%3E%20B%5BPsychological%20Safety%5D%0A%20%20%20%20B%20--%3E%20C%5BSelf-Awareness%5D%0A%20%20%20%20C%20--%3E%20D%5BTeam%20Understanding%5D%0A%20%20%20%20D%20--%3E%20E%5BReady%20for%20Practice%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A"})]),fallback:r(()=>[...u[1]||(u[1]=[n(" Loading... ",-1)])]),_:1})),u[4]||(u[4]=t('<h3 id="sabato-giornata-intera-teoria-pratica" tabindex="-1">Sabato (Giornata intera - Teoria + Pratica) <a class="header-anchor" href="#sabato-giornata-intera-teoria-pratica" aria-label="Permalink to &quot;Sabato (Giornata intera - Teoria + Pratica)&quot;">​</a></h3><p><strong>08:00-09:00 - Colazione e Mindfulness</strong></p><ul><li>Colazione tranquilla</li><li>Meditazione guidata facoltativa di 15 minuti</li><li>Stabilisci le intenzioni per la giornata</li></ul><p><strong>09:00-10:30 - Sessione teorica: Collegare il contenuto all&#39;esperienza</strong></p><p>Scegli 3-4 argomenti dal sito web dell&#39;Accademia ed esplora il gioco interiore:</p><p><strong>Esempi di argomenti:</strong></p><ol><li><p><strong><a href="./educazione/nutrizione/">Nutrizione</a></strong> (20 min)</p><ul><li>&quot;Come cambiano le tue scelte alimentari sotto pressione?&quot;</li><li>&quot;Mangi ciò di cui il tuo corpo ha bisogno o ciò che vuole la tua ansia?&quot;</li><li>Pratica: pianificare l&#39;alimentazione per il giorno della gara</li></ul></li><li><p><strong><a href="./education/mental-strength/">Forza mentale</a></strong> (25 min)</p><ul><li>&quot;Qual è il tuo rapporto con il fallimento?&quot;</li><li>&quot;Come ti parli dopo un errore?&quot;</li><li>Attività: Trasformare il critico interiore in coach interiore</li></ul></li><li><p><strong><a href="./educazione/consapevolezza/">Consapevolezza</a></strong> (25 min)</p><ul><li>&quot;Dove va la tua mente durante la pausa prima del lancio?&quot;</li><li>&quot;Cosa ti distoglie dal momento presente?&quot;</li><li>Pratica: scansione corporea di 5 minuti</li></ul></li><li><p><strong><a href="./educazione/tattiche/">Tattiche</a></strong> (20 min)</p><ul><li>&quot;La tua scelta di tiro è basata sulla strategia o sulla paura?&quot;</li><li>&quot;Quando è meglio andare sul sicuro o correre dei rischi?&quot;</li><li>Discussione: Profili di rischio nel gruppo</li></ul></li></ol><p><strong>10:30-10:45 - Pausa</strong></p><p><strong>10:45-12:30 - Integrazione in pista: esercizi con concentrazione mentale</strong></p><p><strong>Esercizio 1: Decidi il tuo tiro (30 min)</strong></p><p>Dalla <a href="./workshop">Guida al workshop</a> - esercitatevi a riconoscere l&#39;intenzione e il dubbio:</p><ol><li>Annuncia il bersaglio: &quot;Sto sparando al ferro&quot;</li><li>Dichiara sicurezza: &quot;Sono un 7 su 10&quot;</li><li>Indica il pensiero interiore: &quot;La mia voce interiore è preoccupata per il backspin&quot;</li><li>Eseguire il tiro</li><li>Rifletti: &quot;Cosa è successo? Cosa hai imparato?&quot;</li></ol><p><strong>Esercitazione 2: Interferenza cognitiva (30 min)</strong></p><p>Verifica se la tecnica è diventata automatica:</p><ul><li>Il coordinatore pone domande complesse mentre il giocatore spara</li><li>&quot;Nomina 5 capitali&quot; o &quot;Conta all&#39;indietro partendo da 100, di 7 in 7&quot;</li><li>Successo = la tecnica è implicita, non elaborata consapevolmente</li></ul><p><strong>Esercitazione 3: pratica del manuale utente (30 min)</strong></p><p>Applicare i Manuali d&#39;uso da venerdì:</p><ul><li>Gioca in squadre da 3</li><li>Dopo ogni tiro, i compagni di squadra rispondono secondo il Manuale dell&#39;utente</li><li>&quot;Marc ha bisogno di silenzio dopo un errore&quot; - la squadra lo onora</li><li>Debriefing: &quot;Come ti sei sentito ad essere capito?&quot;</li></ul><p><strong>12:30-14:00 - Pranzo e riposo</strong></p><ul><li>Pasto incentrato sulla nutrizione</li><li>Momento di silenzio e riflessione</li><li>Facoltativo: check-in individuali con il coordinatore</li></ul><p><strong>14:00-17:00 - Sessione pratica: Adattamento al terreno</strong></p><p><strong>Obiettivo:</strong> Sviluppare adattabilità e flessibilità mentale</p><p><strong>Impostare:</strong></p><ul><li>Ruota attraverso 3-4 diversi terreni/piste</li><li>45 minuti per terreno</li><li>Concentrarsi sull&#39;adattamento mentale, non solo tecnico</li></ul><p><strong>Struttura di rotazione:</strong></p><table tabindex="0"><thead><tr><th>Terreno</th><th>Concentrazione mentale</th><th>Pratica</th></tr></thead><tbody><tr><td><strong>Terreno 1: Morbido/Sabbia</strong></td><td>Accettazione dell&#39;incertezza</td><td>&quot;Il dato - accetta ciò che è&quot;</td></tr><tr><td><strong>Terreno 2: Duro/Ghiaia</strong></td><td>Precisione sotto pressione</td><td>&quot;Fidati della tua tecnica&quot;</td></tr><tr><td><strong>Terreno 3: Irregolare</strong></td><td>Regolazione emotiva</td><td>&quot;Mantieni la calma quando è ingiusto&quot;</td></tr><tr><td><strong>Terreno 4: Competizione</strong></td><td>Accesso allo stato di flusso</td><td>&quot;Trova la zona&quot;</td></tr></tbody></table><p><strong>Facilitazione:</strong></p><ul><li>L&#39;allenatore tecnico fornisce feedback sulla tecnica</li><li>MPC chiede: &quot;Cosa sta succedendo nella tua mente in questo momento?&quot;</li><li>Diario dei giocatori tra le rotazioni</li></ul><p><strong>17:00-18:00 - Pausa e riflessione</strong></p><ul><li>Diario individuale</li><li>&quot;Cosa hai imparato su te stesso oggi?&quot;</li><li>&quot;Qual è una cosa che farai diversamente domani?&quot;</li></ul><p><strong>18:00-19:00 - Cena</strong></p><p><strong>19:00-21:00 - Teoria serale: Vulnerabilità profonda</strong></p><p><strong>Attività 1: Riformulare il critico interiore (45 min)</strong></p><p>Per il protocollo completo, consultare <a href="./workshop">Guida al workshop</a>:</p><ol><li>Identifica la frase esatta del critico</li><li>Riformulare come Coach Interiore</li><li>Pratica di coppia</li></ol><p><strong>Attività 2: Preparazione alla gara (45 min)</strong></p><p>Domani è il giorno della gara. Preparatevi mentalmente:</p><ol><li><p><strong>Visualizzazione (15 min)</strong></p><ul><li>Chiudi gli occhi</li><li>Immagina lo scatto perfetto</li><li>Senti la sicurezza</li><li>Nota la calma</li></ul></li><li><p><strong>Protocolli di squadra (20 min)</strong></p><ul><li>Creare segnali di supporto</li><li>&quot;Ho bisogno di un reset&quot; = tocco bocce</li><li>&quot;Ho bisogno di incoraggiamento&quot; = pugno chiuso</li><li>&quot;Ho bisogno di spazio&quot; = fai un passo indietro</li></ul></li><li><p><strong>Definisci le intenzioni (10 min)</strong></p><ul><li>&quot;Domani mi concentrerò su...&quot;</li><li>&quot;Il mio obiettivo non è vincere, ma...&quot;</li><li>&quot;Mi eserciterò...&quot;</li></ul></li></ol><p><strong>Check-Out (30 min)</strong></p><ul><li>Condividi una paura per il domani</li><li>Condividi un&#39;intenzione</li><li>Supporto di gruppo</li></ul><p><strong>21:00 - Tempo libero</strong></p><ul><li>A letto presto (domani c&#39;è la gara!)</li><li>Riflessione silenziosa</li></ul><h3 id="domenica-giorno-della-gara" tabindex="-1">Domenica (Giorno della gara) <a class="header-anchor" href="#domenica-giorno-della-gara" aria-label="Permalink to &quot;Domenica (Giorno della gara)&quot;">​</a></h3><p><strong>08:00-09:00 - Colazione e preparazione mentale</strong></p><ul><li>Colazione leggera (vedi <a href="./education/nutrition/">Guida nutrizionale</a>)</li><li>Pratica di consapevolezza di 15 minuti</li><li>Riunioni di squadra</li></ul><p><strong>09:00-09:30 - Briefing sulla gara</strong></p><p><strong>Formato:</strong> Torneo all&#39;italiana</p><ul><li>Squadre da 3</li><li>Gioca fino a 13 punti</li><li>Tutti giocano con tutti</li><li>Concentrarsi sul PROCESSO, non sul risultato</li></ul><p><strong>Il colpo di scena: punteggio delle prestazioni mentali</strong></p><div class="tip custom-block"><p class="custom-block-title">Sistema di punteggio doppio</p><p><strong>Tradizionale:</strong> Punti vinti <strong>Prestazioni mentali:</strong> Valutate da MPC</p><p>Punti prestazione mentale (0-5 per partita):</p><ul><li>Strumenti del manuale utente utilizzati</li><li>Supportare efficacemente i compagni di squadra</li><li>Critico interiore gestito</li><li>Rimanere presenti (senza soffermarsi sugli scatti passati)</li><li>Dimostrata sicurezza psicologica</li></ul><p><strong>Vincitore:</strong> Miglior punteggio combinato (tradizionale + mentale)</p></div><p><strong>09:30-13:00 - Gara mattutina</strong></p><ul><li>Partite all&#39;italiana</li><li>MPC osserva e valuta</li><li>L&#39;allenatore tecnico fornisce un breve feedback tra le partite</li><li>Pause di idratazione e spuntino</li></ul><p><strong>13:00-14:00 - Pranzo</strong></p><ul><li>Incentrato sulla nutrizione</li><li>Riflessione informale</li><li>Riposo</li></ul><p><strong>14:00-17:00 - Gara pomeridiana</strong></p><ul><li>Continua il round-robin</li><li>Semifinali e finali</li><li>Aumento della pressione</li><li>Applicare gli insegnamenti del mattino</li></ul><p><strong>17:00-17:30 - Premi e riconoscimenti</strong></p><p><strong>Categorie:</strong></p><ul><li>Vincitore tradizionale</li><li>Vincitore della prestazione mentale</li><li>Il più migliorato</li><li>Il miglior compagno di squadra</li><li>Premio Coraggio (più vulnerabili)</li></ul><p><strong>17:30-19:00 - Sessione di riflessione finale</strong></p><p><strong>Fondamentale:</strong> È qui che l&#39;apprendimento si consolida.</p><p><strong>Struttura:</strong></p><p><strong>1. Riflessione individuale (15 min)</strong> Scrivi sul diario:</p><ul><li>Cosa hai imparato su te stesso questo fine settimana?</li><li>Cosa ti ha sorpreso?</li><li>Cosa farai di diverso?</li><li>Cosa porti a casa?</li></ul><p><strong>2. Condivisione in piccoli gruppi (30 min)</strong> Gruppi di 4-5:</p><ul><li>Condividere informazioni chiave</li><li>Cosa ti ha colpito di più?</li><li>Cosa è stato più difficile?</li><li>Cosa aveva più valore?</li></ul><p><strong>3. Integrazione completa del gruppo (30 min)</strong> Cerchio in alto:</p><ul><li>Ogni persona condivide UN messaggio chiave</li><li>MPC convalida e collega i temi</li><li>Discussione: &quot;Come applicherai questo?&quot;</li></ul><p><strong>4. Impegni (15 min)</strong></p><ul><li>Ogni persona dichiara un impegno</li><li>&quot;Nella mia prossima competizione...&quot;</li><li>Testimoni e supporti di gruppo</li></ul><p><strong>5. Chiusura (15 min)</strong></p><ul><li>Ringraziare i partecipanti per il coraggio</li><li>Promemoria di riservatezza</li><li>Scambio contatti</li><li>Pianificare il follow-up (sessione online facoltativa)</li></ul><p><strong>19:00 - Cena e partenza</strong></p><h2 id="suggerimenti-per-la-facilitazione" tabindex="-1">Suggerimenti per la facilitazione <a class="header-anchor" href="#suggerimenti-per-la-facilitazione" aria-label="Permalink to &quot;Suggerimenti per la facilitazione&quot;">​</a></h2><h3 id="bilanciamento-tra-teoria-e-pratica" tabindex="-1">Bilanciamento tra teoria e pratica <a class="header-anchor" href="#bilanciamento-tra-teoria-e-pratica" aria-label="Permalink to &quot;Bilanciamento tra teoria e pratica&quot;">​</a></h3><p>::: Attenzione Non sovraccaricare la teoria <strong>L&#39;errore:</strong> Troppo parlare, troppo poco fare</p><p><strong>Il saldo:</strong></p><ul><li>La teoria crea consapevolezza</li><li>La pratica sviluppa le abilità</li><li>Integrazione dei test di concorrenza</li><li>La riflessione cementa l&#39;apprendimento</li></ul><p><strong>Regola pratica:</strong> 30% teoria, 40% pratica, 20% competizione, 10% riflessione :::</p><h3 id="gestire-le-dinamiche-di-gruppo" tabindex="-1">Gestire le dinamiche di gruppo <a class="header-anchor" href="#gestire-le-dinamiche-di-gruppo" aria-label="Permalink to &quot;Gestire le dinamiche di gruppo&quot;">​</a></h3><p><strong>L&#39;Alfa Competitivo:</strong></p><ul><li>Vuole vincere a tutti i costi</li><li>Resiste alla vulnerabilità</li><li><strong>Strategia:</strong> Incanalare la competitività nel punteggio delle prestazioni mentali</li></ul><p><strong>L&#39;osservatore silenzioso:</strong></p><ul><li>Accetta tutto, non condivide</li><li><strong>Strategia:</strong> Creare punti di ingresso a basso rischio, convalidare l&#39;osservazione come partecipazione</li></ul><p><strong>Lo scettico:</strong></p><ul><li>&quot;Questa roba sdolcinata non funziona&quot;</li><li><strong>Strategia:</strong> Aikido verbale - allineare e ruotare (vedere <a href="./workshop">Guida al workshop</a>)</li></ul><p><strong>Colui che condivide troppo:</strong></p><ul><li>Domina la discussione</li><li><strong>Strategia:</strong> &quot;Grazie, sentiamo cosa ne pensano gli altri&quot;</li></ul><h3 id="gestire-i-momenti-emotivi" tabindex="-1">Gestire i momenti emotivi <a class="header-anchor" href="#gestire-i-momenti-emotivi" aria-label="Permalink to &quot;Gestire i momenti emotivi&quot;">​</a></h3><p><strong>Qualcuno piange durante Fear in a Hat:</strong></p><ul><li>✅ Normalizza: &quot;Le lacrime sono coraggio, non debolezza&quot;</li><li>✅ Offri fazzoletti, non avere fretta</li><li>✅ Chiedi: &quot;Di cosa hai bisogno adesso?&quot;</li><li>❌ Non: &quot;Va bene, non piangere&quot;</li></ul><p><strong>Conflitto tra giocatori:</strong></p><ul><li>✅ Pausa e indirizzo</li><li>✅ &quot;Cosa sta succedendo adesso?&quot;</li><li>✅ Utilizzalo come momento di apprendimento</li><li>❌ Non: ignorare o minimizzare</li></ul><p><strong>Qualcuno si spegne:</strong></p><ul><li>✅ Effettua il check-in privato durante la pausa</li><li>✅ &quot;Ho notato che sei diventato silenzioso. Che succede?&quot;</li><li>✅ Opzioni di offerta: partecipa in modo diverso, prenditi una pausa</li><li>❌ Non fare: chiamare pubblicamente</li></ul><h2 id="follow-up-post-campo" tabindex="-1">Follow-up post-campo <a class="header-anchor" href="#follow-up-post-campo" aria-label="Permalink to &quot;Follow-up post-campo&quot;">​</a></h2><h3 id="immediato-24-48-ore" tabindex="-1">Immediato (24-48 ore) <a class="header-anchor" href="#immediato-24-48-ore" aria-label="Permalink to &quot;Immediato (24-48 ore)&quot;">​</a></h3><p><strong>Inviare a tutti i partecipanti:</strong></p><ul><li>Messaggio di ringraziamento</li><li>Riepilogo dei punti chiave</li><li>Foto del fine settimana</li><li>Elenco dei contatti (con autorizzazione)</li><li>Link alle risorse sul sito web</li></ul><p><strong>Check-in individuali:</strong></p><ul><li>Invia un messaggio a chiunque abbia condiviso molto</li><li>&quot;Come ti senti per il fine settimana?&quot;</li><li>Risolvere eventuali problemi di vulnerabilità</li></ul><h3 id="a-breve-termine-2-settimane" tabindex="-1">A breve termine (2 settimane) <a class="header-anchor" href="#a-breve-termine-2-settimane" aria-label="Permalink to &quot;A breve termine (2 settimane)&quot;">​</a></h3><p><strong>Sessione online facoltativa (60-90 min):</strong></p><ul><li>Come hai applicato gli insegnamenti?</li><li>Cosa funziona? Cosa è impegnativo?</li><li>Supporto tra pari e risoluzione dei problemi</li><li>Rafforzare gli impegni</li></ul><h3 id="a-lungo-termine-1-3-mesi" tabindex="-1">A lungo termine (1-3 mesi) <a class="header-anchor" href="#a-lungo-termine-1-3-mesi" aria-label="Permalink to &quot;A lungo termine (1-3 mesi)&quot;">​</a></h3><p><strong>Partecipanti al sondaggio:</strong></p><ul><li>Cosa c&#39;è di diverso nel tuo gioco?</li><li>Quali strumenti utilizzi ancora?</li><li>Cosa renderebbe migliore il prossimo campo?</li><li>Lo consiglieresti ad altri?</li></ul><p><strong>Impatto sulla pista:</strong></p><ul><li>Risultati della competizione</li><li>Fiducia auto-riferita</li><li>Dinamiche di squadra</li><li>Impegno continuo</li></ul><h2 id="adattamento-a-gruppi-di-diverse-dimensioni" tabindex="-1">Adattamento a gruppi di diverse dimensioni <a class="header-anchor" href="#adattamento-a-gruppi-di-diverse-dimensioni" aria-label="Permalink to &quot;Adattamento a gruppi di diverse dimensioni&quot;">​</a></h2><h3 id="piccolo-campo-10-12-giocatori" tabindex="-1">Piccolo campo (10-12 giocatori) <a class="header-anchor" href="#piccolo-campo-10-12-giocatori" aria-label="Permalink to &quot;Piccolo campo (10-12 giocatori)&quot;">​</a></h3><p><strong>Vantaggi:</strong></p><ul><li>Condivisione più profonda</li><li>Maggiore attenzione individuale</li><li>Legami più forti</li></ul><p><strong>Modifiche:</strong></p><ul><li>Gruppo unico per tutta la teoria</li><li>Più tempo a persona dedicato alle attività</li><li>Formato di competizione intima</li></ul><h3 id="campo-grande-16-20-giocatori" tabindex="-1">Campo grande (16-20 giocatori) <a class="header-anchor" href="#campo-grande-16-20-giocatori" aria-label="Permalink to &quot;Campo grande (16-20 giocatori)&quot;">​</a></h3><p><strong>Vantaggi:</strong></p><ul><li>Prospettive diverse</li><li>Maggiore varietà di competizioni</li><li>Economie di scala</li></ul><p><strong>Modifiche:</strong></p><ul><li>Divisi in 2 gruppi per alcune sessioni teoriche</li><li>Sono necessari 2 MPC/facilitatori</li><li>Tabellone del torneo più ampio</li><li>Rotazioni più strutturate</li></ul><h2 id="considerazioni-sul-budget" tabindex="-1">Considerazioni sul budget <a class="header-anchor" href="#considerazioni-sul-budget" aria-label="Permalink to &quot;Considerazioni sul budget&quot;">​</a></h2><h3 id="reddito" tabindex="-1">Reddito <a class="header-anchor" href="#reddito" aria-label="Permalink to &quot;Reddito&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Articolo</th><th>Prezzo a persona</th><th>20 persone</th><th>10 persone</th></tr></thead><tbody><tr><td><strong>Registrazione</strong></td><td>€150-250</td><td>€3.000-5.000</td><td>€1.500-2.500</td></tr></tbody></table><h3 id="spese" tabindex="-1">Spese <a class="header-anchor" href="#spese" aria-label="Permalink to &quot;Spese&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Categoria</th><th>Costo</th><th>Note</th></tr></thead><tbody><tr><td><strong>Affitto struttura</strong></td><td>€500-1.000</td><td>Tariffa weekend</td></tr><tr><td><strong>Alloggio</strong></td><td>€40-60/persona/notte</td><td>Camere condivise</td></tr><tr><td><strong>Pasti</strong></td><td>€30-40/persona/giorno</td><td>6 pasti</td></tr><tr><td><strong>Personale</strong></td><td>€500-1.000</td><td>MPC + allenatori</td></tr><tr><td><strong>Materiali</strong></td><td>€100-200</td><td>Schede didattiche, materiali</td></tr><tr><td><strong>Premi</strong></td><td>€100-200</td><td>Articoli di riconoscimento</td></tr></tbody></table><p><strong>Totale a persona:</strong> €120-180 <strong>Margine:</strong> € 30-70/persona (o pareggio per la creazione di comunità)</p><h2 id="metriche-di-successo" tabindex="-1">Metriche di successo <a class="header-anchor" href="#metriche-di-successo" aria-label="Permalink to &quot;Metriche di successo&quot;">​</a></h2><h3 id="indicatori-immediati" tabindex="-1">Indicatori immediati <a class="header-anchor" href="#indicatori-immediati" aria-label="Permalink to &quot;Indicatori immediati&quot;">​</a></h3><ul><li>[ ] Punteggio di sicurezza psicologica (media 1-10 &gt;7)</li><li>[ ] Tasso di partecipazione (&gt;80% di condivisione attiva)</li><li>[ ] Tasso di completamento (&gt;90% rimane per tutto il fine settimana)</li><li>[ ] Punteggio di soddisfazione (media 1-10 &gt;8)</li></ul><h3 id="indicatori-a-lungo-termine" tabindex="-1">Indicatori a lungo termine <a class="header-anchor" href="#indicatori-a-lungo-termine" aria-label="Permalink to &quot;Indicatori a lungo termine&quot;">​</a></h3><ul><li>[ ] Cambiamento del comportamento (utilizzo di strumenti in competizione)</li><li>[ ] Miglioramento delle prestazioni (auto-riportato)</li><li>[ ] Creazione di comunità (restare in contatto)</li><li>[ ] Riferimenti (raccomandazione ad altri)</li></ul><h2 id="errori-comuni-da-evitare" tabindex="-1">Errori comuni da evitare <a class="header-anchor" href="#errori-comuni-da-evitare" aria-label="Permalink to &quot;Errori comuni da evitare&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Insidie</p><p><strong>1. Troppi contenuti</strong></p><ul><li>Cercando di coprire tutto</li><li><strong>Correzione:</strong> Concentrarsi sulla profondità, non sull&#39;ampiezza</li></ul><p><strong>2. Saltare la riflessione</strong></p><ul><li>Correre verso l&#39;attività successiva</li><li><strong>Correzione:</strong> Tempo di elaborazione predefinito</li></ul><p><strong>3. Ignorare la resistenza</strong></p><ul><li>Superare lo scetticismo</li><li><strong>Correzione:</strong> Affrontalo direttamente con l&#39;Aikido Verbale</li></ul><p><strong>4. Coaching tecnico durante la teoria</strong></p><ul><li>Mescolare i ruoli</li><li><strong>Correzione:</strong> Chiari confini tra MPC e allenatore tecnico</li></ul><p><strong>5. Nessun follow-up</strong></p><ul><li>Fine settimana, stop all&#39;apprendimento</li><li><strong>Correzione:</strong> Pianifica i punti di contatto post-camp</li></ul></div><h2 id="risorse" tabindex="-1">Risorse <a class="header-anchor" href="#risorse" aria-label="Permalink to &quot;Risorse&quot;">​</a></h2><h3 id="da-questo-sito" tabindex="-1">Da questo sito <a class="header-anchor" href="#da-questo-sito" aria-label="Permalink to &quot;Da questo sito&quot;">​</a></h3><ul><li><a href="./workshop">Guida al workshop</a> - Protocolli di facilitazione dettagliati</li><li><a href="./training-session">Guida alla sessione di allenamento</a> - Per la pratica continua</li><li><a href="./education/nutrition/">Nutrizione</a> - Protocolli per il giorno della gara</li><li><a href="./education/mental-strength/">Forza mentale</a> - Concetti di gioco interiore</li><li><a href="./education/mindfulness/">Mindfulness</a> - Tecniche di presenza</li><li><a href="./education/tactics/">Tattiche</a> - Pensiero strategico</li></ul><h3 id="letture-consigliate" tabindex="-1">Letture consigliate <a class="header-anchor" href="#letture-consigliate" aria-label="Permalink to &quot;Letture consigliate&quot;">​</a></h3><ul><li><em>Il gioco interiore del tennis</em> di Timothy Gallwey</li><li><em>Mentalità</em> di Carol Dweck</li><li><em>L&#39;organizzazione senza paura</em> di Amy Edmondson</li></ul>',138))])}]]);export{u as __pageData,c as default};
